 if(!d.complete){if(!humanSide(d.next))return {label:'Bot is deploying',disabled:true};return d.pending?{label:`Confirm ${pieceName(d.pending)}`,disabled:false}:{label:`${armyName(d.next)}: place a unit`,disabled:true};}
 if(!f)return {label:'Roll off for the first turn',disabled:false};
 if(!f.chosen)return {label:humanSide(f.winner)?'Choose who goes first':'Bot is choosing',disabled:true};
