  if(aiMode==='ai'&&AI.deploymentChoice(state)){const out=AI.takeDeploymentStep(state),next=G.deploymentTurn(state);selectNextReserve(next);notify(out.message+(next&&humanSide(next)&&!autoPlace?' Your turn to deploy a unit.':''));}
  else if(autoPlace&&G.deploymentTurn(state)&&humanSide(G.deploymentTurn(state))){const out=G.autoDeploy(state,{team:G.deploymentTurn(state)});notify(`${pieceName(out.id)} deployed.`);}
  if(state.deployOrder.complete)autoPlace=false;
