  $('opponentZone').textContent=armyName('iron').toUpperCase()+(zoneDepth('iron')?` / ${zoneDepth('iron')}″ DEPLOYMENT`:' / DEPLOYMENT ZONE');$('ashZone').textContent=armyName('ash').toUpperCase()+(zoneDepth('ash')?` / ${zoneDepth('ash')}″ DEPLOYMENT`:' / DEPLOYMENT ZONE');$('opponentZone').setAttribute('class','zone-label '+(state.units.find(v=>v.team==='iron').faction==='orc'?'orc-text':'iron-text'));$('board').setAttribute('aria-label',`Battlefield, ${state.board.width} by ${state.board.height} inches. Red deploys at the bottom, `+(state.units.find(v=>v.team==='iron').faction==='orc'?'green Orcs':'blue Empire State Troops')+' at the top.');$('opponentRosterTitle').textContent=armyName('iron').toUpperCase();for(const team of ['ash','iron'])$(team+'ModelCount').textContent=state.units.filter(u=>u.team===team).reduce((n,u)=>n+(G.isCharacter(u)?1:G.startingModels(u)),0)+' models';$('opponentLegend').textContent=armyName('iron');$('opponentDot').className='dot '+state.units.find(v=>v.team==='iron').faction;$('opponentRosterDot').className='dot '+state.units.find(v=>v.team==='iron').faction;
