function point(e){const p=$('board').createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform($('board').getScreenCTM().inverse());return {x:q.x/S,y:q.y/S};}
$('board').addEventListener('pointerdown',e=>{
  if(e.button!==0)return;const objective=e.target.closest('[data-objective].movable');if(objective&&BM.canPlaceObjectives(state)){const p=point(e),o=state.objectives.items.find(v=>v.id===objective.dataset.objective);hideUnitTooltip();drag={objective:o.id,dx:p.x-o.x,dy:p.y-o.y,startX:e.clientX,startY:e.clientY,moving:false,pointerId:e.pointerId};$('board').setPointerCapture(e.pointerId);return;}const rocket=e.target.closest('[data-rocket]'),cannon=e.target.closest('[data-cannon]'),machineId=rocket?.dataset.rocket??cannon?.dataset.cannon;if(machineId&&state.stage==='shooting'&&rocketSelected&&cannon){rocketTarget=machineId;render();return;}if(machineId&&state.stage==='shooting'&&cannonSelected&&rocket){cannonTarget=machineId;render();return;}if(machineId&&state.stage==='movement'&&state.movementStep==='declare'&&ordersOpen&&G.getUnit(state)?.team===state.team&&G.getUnit(state,machineId)?.team!==state.team){chargeTarget=machineId;render();return;}if(rocket){rocketSelected=true;cannonSelected=null;ordersOpen=false;rocketTarget=null;render();return;}if(cannon){cannonSelected=cannon.dataset.cannon;rocketSelected=false;ordersOpen=false;cannonTarget=null;render();return;}const g=e.target.closest('[data-unit]'),p=point(e);hideUnitTooltip();
  if(g){const id=g.dataset.unit;select(id,state.stage!=='deployment');if(state.stage==='deployment'&&!botOwns(id)&&!G.getUnit(state,id).deployed){const u=G.getUnit(state);drag={id,dx:p.x-u.x,dy:p.y-u.y,startX:e.clientX,startY:e.clientY,moving:false,pointerId:e.pointerId};$('board').setPointerCapture(e.pointerId);}}
  else if(state.stage==='deployment'&&rocketSelected){safely(()=>{G.placeRocket(state,p.x,p.y);notify(placedNote('Deathshrieker','Deathshrieker deployed with its crew.'));});}else if(state.stage==='deployment'&&cannonSelected){safely(()=>{if(aiMode==='ai')throw Error('The bot deploys its own cannons.');G.placeCannon(state,cannonSelected,p.x,p.y);notify(placedNote(pieceName(cannonSelected),cannonSelected+' deployed with its crew.'));});}else if(state.stage==='deployment'){closeOrders();placeSelected(p.x,p.y);}else{rocketSelected=false;cannonSelected=null;closeOrders();render();}
});
$('board').addEventListener('pointermove',e=>{if(!drag)return;if(drag.objective){dragObjective(e);return;}if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>4)drag.moving=true;if(!drag.moving)return;const p=point(e),u=G.getUnit(state,drag.id);drag.x=Math.round((p.x-drag.dx)*2)/2;drag.y=Math.round((p.y-drag.dy)*2)/2;$('ghostLayer').replaceChildren();const ghost=drawUnit({...u,x:drag.x,y:drag.y},$('ghostLayer'),true);if(G.checkPosition(state,u,drag.x,drag.y,true))ghost.querySelector('rect').classList.add('invalid');});
function endDrag(e,cancel=false){if(!drag)return;const d=drag;drag=null;$('ghostLayer').replaceChildren();if($('board').hasPointerCapture(d.pointerId))$('board').releasePointerCapture(d.pointerId);if(cancel)return;if(d.objective){if(d.moving)safely(()=>{BM.placeObjective(state,d.objective,d.x,d.y);notify(`${d.objective} moved. Troves stay 3″ clear of terrain and on the battlefield.`);});return;}if(d.moving)safely(()=>{G.place(state,d.id,d.x,d.y);$('deployX').value=d.x;$('deployY').value=d.y;notify(`${d.id} repositioned.`);});else{ordersOpen=true;renderOrders();}}
$('board').addEventListener('pointerup',e=>endDrag(e));$('board').addEventListener('pointercancel',e=>endDrag(e,true));
$('rulesButton').onclick=()=>$('rulesDialog').showModal();$('closeRules').onclick=()=>$('rulesDialog').close();$('resetButton').onclick=()=>$('resetDialog').showModal();$('cancelReset').onclick=()=>$('resetDialog').close();
{const ref=$('spellReference');for(const [key,spell]of Object.entries(G.BATTLE_MAGIC)){const p=document.createElement('p');p.innerHTML=`<b>${spell.name}</b> · ${title(spell.type)} · ${spell.cast}+ · ${spell.range?spell.range+'″':['hammerhand','hashutFlames'].includes(key)?'Combat':'Self'}${['hashutCurse','ashStorm','hashutFlames'].includes(key)?' · Lore of Hashut (Daemonsmith signature)':''}<br>`;p.append(G.SPELL_TEXT[key]??'');ref.append(p);}}
function setupOptions(){const format=$('formatSelect').value;if(format==='classic')return {format};return {format,points:Number($('pointsSelect').value),board:$('boardSelect').value,deployment:{map:$('mapSelect').value,depth:Number($('depthInput').value)},objectives:$('objectivesSelect').value,optional:Object.fromEntries(Object.keys(F.OPTIONAL_RULES).map(key=>[key,$('opt-'+key).checked]))};}
