function newGame(message='Choose an opponent, then deploy all regiments and war machines or use Quick deploy.'){$('diceAnimation').hidden=true;chargeTarget=null;shootTarget=null;rocketTarget=null;rocketSelected=false;cannonSelected=null;cannonTarget=null;cannonMode='ball';cannonAimShort=6;rocketProfile='demolition';rocketIndirect=false;manualOrders=null;autoPlace=false;resultShown=false;seenRaids=null;clearTimeout(deployTimer);deployTimer=null;if($('resultDialog').open)$('resultDialog').close();state=G.createGame($('opponentSelect').value,setupOptions());rolls=[];ordersOpen=false;resetOrder();$('diceResults').innerHTML='<span class="empty-die">?</span><span class="empty-die">?</span>';$('diceSummary').textContent='';$('boardRoll').textContent='';$('rollHistory').innerHTML='<li>No rolls yet.</li>';render();notify(message);}
