function changeSetup(){if($('formatSelect').value==='battle-march'&&$('opponentSelect').value==='orc'){$('opponentSelect').value='empire';notify('Orcs cannot field a Battle March General in this game yet, so the Empire army is used.');}try{newGame(state.format.id==='battle-march'?`Battle March · ${state.format.points} points on a ${state.board.width}″ × ${state.board.height}″ battlefield. Deploy your army.`:'Classic battle on a 72″ × 48″ battlefield. Deploy your army.');}catch(e){notify(e.message,true);}}
$('formatSelect').onchange=changeSetup;$('boardSelect').onchange=changeSetup;$('mapSelect').onchange=changeSetup;$('depthInput').onchange=changeSetup;
$('pointsSelect').onchange=()=>{$('boardSelect').value=F.boardFor('battle-march',{points:Number($('pointsSelect').value)}).id;changeSetup();};
function renderSetup(deploy){
 $('formatSetup').hidden=!deploy;if(!deploy)return;const bm=state.format.id==='battle-march';$('formatSelect').value=state.format.id;
 for(const id of ['pointsPicker','boardPicker','mapPicker','depthPicker','objectivesPicker','optionalRules'])$(id).hidden=!bm;
 if(bm){$('objectivesSelect').value=state.format.objectives;for(const key of Object.keys(F.OPTIONAL_RULES))$('opt-'+key).checked=!!state.format.optional[key];}
 if(bm){$('pointsSelect').value=String(state.format.points);$('boardSelect').value=state.board.id;$('mapSelect').value=state.format.deployment.map;$('depthInput').value=String(state.format.deployment.depth);}
 $('opponentSelect').querySelector('[value="orc"]').disabled=bm;$('opponentSelect').querySelector('[value="orc"]').textContent=bm?'Orc Mob · green (no Battle March General yet)':'Orc Mob · green';
 const summary=$('rosterSummary');summary.replaceChildren();if(bm)for(const team of ['ash','iron']){const army=state.armies[team],v=army.validation,box=document.createElement('section');box.className='roster-card '+team;
  box.innerHTML=`<header><b>${armyName(team)}</b><span class="${v.legal?'legal':'illegal'}">${v.total} / ${v.points} pts · ${v.legal?'legal Battle March army':'not legal'}</span></header><ol></ol>`;
  const list=box.querySelector('ol');for(const item of army.roster.entries){const e=A.entryOf(army.roster.faction,item.entry),li=document.createElement('li'),cmd=Object.keys(item.command??{}).filter(k=>item.command[k]).map(k=>e.command[k].name).join(', ');li.textContent=`${item.general?'General · ':''}${item.models?item.models+' ':''}${e.name}${cmd?' · '+cmd:''} — ${A.entryCost(army.roster.faction,item)}`;list.append(li);}
  if(!v.legal){const ul=document.createElement('ul');ul.className='roster-errors';for(const err of v.errors){const li=document.createElement('li');li.textContent=err;ul.append(li);}box.append(ul);}
  const src=document.createElement('small');src.textContent=`Costs: ${army.source.name}, revision ${army.source.revision}.`;box.append(src);summary.append(box);}
 $('formatNote').textContent=bm?`Five rounds; objectives score at the end of every player turn. Units deploy one at a time after a roll-off. Deployment uses a custom long-edge preset: the six official Battle March maps need their diagrams before they can be used. Result rule: ${state.format.resultPolicy.confirmed?'confirmed':'core rulebook 100 VP margin, not yet confirmed for Battle March'}.`:'Open-ended classic battle on the full-size table.';
}
