 const weapon=G.missileWeapon(u);$('shootingHelp').textContent=u.fleeing?'Fleeing units cannot shoot.':u.movementMode==='march'?'This unit marched and cannot shoot this turn.':`${weapon.name} · ${weapon.range}″ range · ${weapon.range/2}″ close / 50% · ${weapon.strength} Strength · AP −${weapon.ap}. ${weapon.multiple?'D3 shots per model; Volley Fire. ':''}Click a highlighted enemy on the board.`;
